mapper.select:
select r.record_id, r.user_id, r.audit_type, r.audit_status, r.audit_by, r.audit_by_name,
       r.audit_remark, r.id_card_front, r.id_card_back, r.create_time, r.audit_time,
       u.user_name, u.real_name, u.phonenumber
from ee_audit_record r
left join sys_user u on r.user_id = u.user_id


        AND r.audit_status = #{auditStatus}


        AND r.audit_type = #{auditType}


        AND r.user_id = #{userId}


order by r.create_time desc
